#include "stdafx.h"#include "..\MnemoWnd.h"#include "Queue.h"#include "..\Lang.h"//#define PAINTEX PAINT, char* szValue//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структура работы с переменнымиtypedef struct : public SPROLOZ  {  SValueDef* defOut;  char szText[32];//Для настройки  char szMeas[32];//Единицы измерения  RECT rect;  int    mAlign;  int     mEdge;// Вывод рамки  COLORREF mTxt;// Вывод текста  COLORREF mBkg;// Вывод фона  COLORREF mColor;//фон для моих, зеленый по умолчанию  void PaintDbl( PAINTEX );  void PaintInt( PAINTEX );  void PaintI64( PAINTEX );  void PaintChr( PAINTEX );  void PaintBol( PAINTEX );  void PaintFlt( PAINTEX );  void PaintStr( PAINTEX );  int  nTeg;  UINT eType;  bool bColorEdge;  bool bRamka;  int  nHS;  int nEqual;  int nNoEqual;  bool bGreen;  bool bIsGreen;  } Queue_Val;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияvoid Queue_Val::PaintDbl( PAINTEX )  {  SParamValue var(nNumber,defOut);  q.m_pPipe->FillValue( szValue, var, nFloat, NULL );  //int dLength=sizeof(szValue);  //for (int i=0;i<dLength;i++)	 // if (szValue[i]=='.')	 // {		//  szValue[i]=',';		//  return;	 // }  }//void Queue_Val::PaintInt( PAINTEX )  {  SParamValue var(nNumber,defOut);  int i=q.m_pPipe->ValueI(var);  sprintf_s( szValue, 512, "%d", i );  }//void Queue_Val::PaintI64( PAINTEX )  {  ASSERT(0);  }//void Queue_Val::PaintChr( PAINTEX )  {  ASSERT(0);  }//void Queue_Val::PaintBol( PAINTEX )  {  ASSERT(0);  }//void Queue_Val::PaintFlt( PAINTEX )  {  ASSERT(0);  }//void Queue_Val::PaintStr( PAINTEX )  {  ASSERT(0);  }//// Функция отображенияint PaintVal(DefinePaint)  {  QueueP(Queue_Val);  COLORREF color = p->mTxt;  char szValue[512] = "###";  CShBase* sh = PipeSh;  //  if ( p->defOut == NULL )    {    CMyBrush brush(hDC,0xff00ff);    brush.Rect( p->rect );    }  else  if ( *p->szText )    {    lstrcpy( szValue, p->szText );	if ( ::IsMnemoStyle(MNEMO_EDIT) )		  color = 0x80ff;    }  else  if ( IsTypeOk )    {    color = p->mTxt;    switch ( p->defOut->eVal )      {      case enumValueDbl:p->PaintDbl( hDC, q, szValue );break;      case enumValueInt:p->PaintInt( hDC, q, szValue );break;      case enumValueI64:p->PaintI64( hDC, q, szValue );break;      case enumValueChr:p->PaintChr( hDC, q, szValue );break;      case enumValueBol:p->PaintBol( hDC, q, szValue );break;      case enumValueFlt:p->PaintFlt( hDC, q, szValue );break;      case enumValueStr:p->PaintStr( hDC, q, szValue );break;      };    if ( *p->szMeas )      {      lstrcat( szValue, " " );      lstrcat( szValue, p->szMeas );      }    }  //  if ( p->mBkg != 0xffffffff )    {    CMyBrush brush(hDC,p->mBkg);    brush.Rect( p->rect );    }  //  if(p->bColorEdge)  {	  const double dBadValue=-1021;	  double dHH = TegValueD( p->nTeg, "HH", dBadValue );	  double dH = TegValueD( p->nTeg, "H", dBadValue );	  double dLL = TegValueD( p->nTeg, "LL", dBadValue );	  double dL = TegValueD( p->nTeg, "L", dBadValue );	  char* szValueTemp = (char*)::TegValueS( p->nTeg, "value", "0" );	  if (lstrcmp(szValueTemp,"0")!=0)			lstrcpy(szValue,szValueTemp);	  COLORREF clr=p->mColor;	  double dValue=atof(szValue);	  if (dL!=dBadValue)		  if (dValue<=dL)			  clr=0x02ccff;	  if (dLL!=dBadValue)          if (dValue<=dLL)			  clr=RGB(255,0,0);	  if (dH!=dBadValue)		  if (dValue>=dH)			  clr=0x02ccff;	  if (dHH!=dBadValue)          if (dValue>=dHH)			  clr=RGB(255,0,0);	  p->bIsGreen=p->bGreen;	  if ( p->nHS >= 0 )      {			CShHS& Sh = (CShHS&)q.m_pPipe->SH(p->nHS);			int nState;			if ( Sh.RetCode == CShBase::rcOK )			{      if ( Sh.mOn )        nState = 1;      else        nState = 0;//##??				nState = Sh.PV; //##??				if (p->nEqual!=-1)					p->bIsGreen=(nState==p->nEqual);				if (p->nNoEqual!=-1)					p->bIsGreen=(nState!=p->nNoEqual);			}      }	  if (p->bIsGreen)		  clr=RGB(0,255,0);	  CMyBrush brush(hDC,clr);	  brush.Rect( p->rect );	  if(p->bRamka)			clr=0x000000;	  CMyPen pen(hDC,clr);	  pen.Rect( p->rect );  }  if (lstrcmp(szValue,"###")==0)  {	  if ( ::IsMnemoStyle(MNEMO_EDIT) )		  color = 0x80ff;	  else	  {		        char strFormat[16];		  		sprintf_s(strFormat,"%%.%dlf",p->nFloat);				sprintf_s(szValue,strFormat,0.);	  }  }  CMyFont font( hDC, NULL, color );  font.DrawS( p->rect, szValue, p->mAlign );  //  if ( p->mEdge )    ::DrawEdge( hDC, &p->rect, p->mEdge, BF_RECT );  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddVal(DefineTegs)  {  AddQueueEx(Queue_Val);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint  = &PaintVal;  p->mBkg   = 0xffffffff;  p->mColor=RGB(0,255,0);  p->mAlign = DT_CENTER;  p->bColorEdge=false;  p->bRamka=true;  char szObj[32] = "Value";  p->nEqual=-1;  p->nNoEqual=-1;  p->bGreen=false;  p->nHS=-1;  p->bIsGreen=false;  char szHS[64] = "";  //  STegObj obj[] =    {    { 'I', "edge" , &p->mEdge    },    { 'A', "txt"  , &p->mTxt     },    { 'A', "bkg"  , &p->mBkg     },    { 'W', "align", &p->mAlign   },    { 'S', "text" ,  p->szText,31},    { 'S', "meas" ,  p->szMeas,31},    { 'S', "obj"  ,  szObj,31},	{ 'B', "colorEdge",&p->bColorEdge},	{ 'B', "ramka",&p->bRamka},	{ 'A', "color"  , &p->mColor     },	{ 'I', "equal", &p->nEqual },	{ 'I', "noequal", &p->nNoEqual },	{ 'B', "green", &p->bGreen },	{ 'S', "view", szHS, 63 },    // Дополнительная информация    EXT_QUEUE    };  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  // Форматы: (Name.Param) | (Name) | (.Param) | (.)  // Текущий активный элемент  bool bActive = *teg[0].value == '.';  static char* DEF = "DBL";  char* parm = strchr( teg[0].value, '.' );  if ( parm == NULL ) parm = DEF;  else *parm++ = 0;  //  UINT eType;  if ( bActive )    {    p->nNumber = def.GetActiveObj();    eType = def.GetMnemoType( p->nNumber );    }  else    {    eType = TextToType( szObj );    p->nNumber = def.AddKindEx( eType, teg[0].value );    }  if (p->bColorEdge)  {		p->nTeg = ::FindTagEx( teg[0].value, eType );  }  p->eType=eType;  p->defOut = NameToValue( eType, parm );  ASSERT( p->defOut != NULL );  //  p->rect = p->mRect;  if ( *szHS )	  p->nHS = def.AddKind(id_HS,szHS);  if ( p->mEdge != 0 )// Чтобы рамка не наезжала на текст    ::InflateRect( &p->rect, -2, -2 );  if ( !::IsMnemoStyle(MNEMO_EDIT) )    ::SetRectEmpty( &p->mRect );  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~